css:
/* ==== INTERFACE ====
   token  --bg #F4F6F8            底色｜全课唯一的冷灰平涂画板底
   token  --text #1A222C          正文文本、重要公式项、结构主标签
   token  --muted #586675         次要说明、刻度文字、无动作状态（与底对比度 5.1:1）
   token  --rule #CBD3DA          仅限真实分隔线、坐标轴与离散刻度标尺，不可用于围合区块
   token  --flow #2B5C8F          主工作色（占主要有色面积）｜前向计算、网络连接拓扑、输入特征张量、状态推移
   token  --delta #C03E1B         小面积锐利强调色（警戒面积≤5%）｜反向梯度误差、损失残差、高注意力聚焦、当前交互扰动
   token  --focus #1A5499         交互控件获得键盘焦点时的外部轮廓
   token  --font-sans             主要标题与交互界面文字（系统正黑与西文无衬线族）
   token  --font-serif            数学变量、概念定义及推演导语（衬线族）
   token  --font-mono             数值标量、矩阵张量数据、状态数组与微型代码
   token  --fs-h1 34px            页面大标题
   token  --fs-h2 22px            结构与机制区块标题
   token  --fs-lead 19px          机制引言与因果导语
   token  --fs-body 18px          概念阐述与图解说明正文
   token  --fs-sec 16px           副级因果注释与步进说明
   token  --fs-label 15px         交互控件、张量维度与图例标签
   token  --fs-tick 13px          纯数值刻度、时间步编号与矩阵下标
   版心   1488×844                #stage 已含 padding
   论点   以工业计算图纸的冷调中性灰为基底，确立单一主色（工程前向流）与极差悬殊的警示强调（反向误差与注意力焦点），拒绝任何无意义卡片与分色装饰。
   材质   哑光工科实验图表：纯色平面、平坦冷灰中性系统、机械刻度标尺线，绝不使用渐变或彩色光晕。
   签名   前向流向与反向误差的严格双色张力映射：所有承载结构一律以冷深蓝表达，错误与突触调节一律以锐利铁锈红点刺。
   禁令   禁止给任何内容块包裹卡片背景或边框框体；禁止使用除 --flow 与 --delta 之外的第三种非中性语义色；禁止为文字或线条附加任何发光与投影效果。
   修订   原本打算用蓝、绿、橙区分 CNN、RNN 与 MLP 三种网络架构，改为主色负责所有架构的稳定结构，仅用单点铁锈红标记参数误差与激活峰值，消除平均分色并把明度极差拉开到 28pp 以上。
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;

  /* 中性系统：冷调工程图纸 */
  --bg: #F4F6F8;
  --text: #1A222C;
  --muted: #586675;
  --rule: #CBD3DA;
  --focus: #1A5499;

  /* 语义体系：一个主色扛整页 + 一个小面积锐利强调 */
  --flow: #2B5C8F;
  --delta: #C03E1B;

  /* 字体家族 */
  --font-sans: "Noto Sans CJK SC", "Noto Sans Display", "Inter", "Lato", sans-serif;
  --font-serif: "Noto Serif CJK SC", "TeX Gyre Pagella", "AR PL SungtiL GB", serif;
  --font-mono: "Noto Sans Mono", "Latin Modern Mono", "WenQuanYi Zen Hei Mono", monospace;

  /* 投影环境字阶规范（多行行高严格保证 ≥ 1.35） */
  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --lh-tight: 1.35;
  --lh-body: 1.5;
  --lh-heading: 1.25;

  /* 动效与交互节奏 */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 160ms;
  --duration-base: 240ms;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --duration-fast: 0ms;
    --duration-base: 0ms;
  }
}
